create table if not exists public.customer_cashback_ledger(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,referral_id uuid references public.customer_referrals(id) on delete set null,event_type text not null check(event_type in('CREDIT','REVERSAL','REDEMPTION')),points_delta integer not null,amount_delta numeric(12,2) not null,idempotency_key text not null unique,reason text,created_at timestamptz not null default now(),created_by uuid default auth.uid()); alter table public.customer_cashback_ledger enable row level security;